CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '' CHECK (char_length(display_name) <= 100));
GRANT SELECT, INSERT, UPDATE ON public.profiles TO authenticated;
GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY profiles_own_read ON public.profiles FOR SELECT TO authenticated USING (id = auth.uid());
CREATE POLICY profiles_own_insert ON public.profiles FOR INSERT TO authenticated WITH CHECK (id = auth.uid());
CREATE POLICY profiles_own_update ON public.profiles FOR UPDATE TO authenticated USING (id = auth.uid()) WITH CHECK (id = auth.uid());
CREATE FUNCTION public.create_editor_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN INSERT INTO public.profiles (id, display_name) VALUES (NEW.id, left(coalesce(NEW.raw_user_meta_data->>'full_name', ''),100)) ON CONFLICT DO NOTHING; RETURN NEW; END; $$;
CREATE TRIGGER create_editor_profile AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_editor_profile();
CREATE TABLE public.assessments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL DEFAULT auth.uid(), project text NOT NULL CHECK (char_length(project) BETWEEN 3 AND 120), details text NOT NULL CHECK (char_length(details) BETWEEN 10 AND 3000), skills text NOT NULL CHECK (char_length(skills) BETWEEN 2 AND 1000), tone text NOT NULL DEFAULT 'Confident' CHECK (tone IN ('Confident','Professional','Playful')), copy jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(owner_id));
GRANT SELECT ON public.assessments TO anon;
GRANT SELECT, INSERT, UPDATE ON public.assessments TO authenticated;
GRANT ALL ON public.assessments TO service_role;
ALTER TABLE public.assessments ENABLE ROW LEVEL SECURITY;
CREATE POLICY assessment_public_read ON public.assessments FOR SELECT TO anon, authenticated USING (true);
CREATE POLICY assessment_owner_insert ON public.assessments FOR INSERT TO authenticated WITH CHECK (owner_id = auth.uid());
CREATE POLICY assessment_owner_update ON public.assessments FOR UPDATE TO authenticated USING (owner_id = auth.uid()) WITH CHECK (owner_id = auth.uid());
CREATE TABLE public.applications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), assessment_id uuid NOT NULL REFERENCES public.assessments(id), name text NOT NULL CHECK (char_length(name) BETWEEN 2 AND 100), email text NOT NULL CHECK (char_length(email) BETWEEN 3 AND 255), portfolio text NOT NULL DEFAULT '' CHECK (char_length(portfolio) <= 500), skills text NOT NULL CHECK (char_length(skills) BETWEEN 2 AND 1000), motivation text NOT NULL CHECK (char_length(motivation) BETWEEN 10 AND 3000), status text NOT NULL DEFAULT 'New' CHECK (status IN ('New','Shortlisted','Reviewed')), created_at timestamptz NOT NULL DEFAULT now());
GRANT INSERT ON public.applications TO anon;
GRANT INSERT, SELECT, UPDATE ON public.applications TO authenticated;
GRANT ALL ON public.applications TO service_role;
ALTER TABLE public.applications ENABLE ROW LEVEL SECURITY;
CREATE POLICY application_public_submit ON public.applications FOR INSERT TO anon, authenticated WITH CHECK (status = 'New' AND EXISTS (SELECT 1 FROM public.assessments WHERE id = assessment_id));
CREATE POLICY application_owner_read ON public.applications FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.assessments WHERE id = assessment_id AND owner_id = auth.uid()));
CREATE POLICY application_owner_update ON public.applications FOR UPDATE TO authenticated USING (EXISTS (SELECT 1 FROM public.assessments WHERE id = assessment_id AND owner_id = auth.uid())) WITH CHECK (EXISTS (SELECT 1 FROM public.assessments WHERE id = assessment_id AND owner_id = auth.uid()));
CREATE INDEX applications_assessment_idx ON public.applications(assessment_id, created_at DESC);